SET FOREIGN_KEY_CHECKS=0;
START TRANSACTION;

-- ===== FINISHED GOODS (from BOM headers) =====

-- ===== RAW MATERIALS / COMPONENTS (from BOM details) =====

-- ===== LINK bom_headers.product_id =====
UPDATE bom_headers bh JOIN products p ON bh.bom_code = p.sku SET bh.product_id = p.id WHERE bh.product_id IS NULL AND bh.bom_code IS NOT NULL;

-- ===== LINK bom_details.raw_material_id =====
UPDATE bom_details bd JOIN products p ON bd.item_code = p.sku SET bd.raw_material_id = p.id WHERE (bd.raw_material_id IS NULL OR bd.raw_material_id = 0) AND bd.item_code IS NOT NULL AND bd.item_code != '';

COMMIT;
SET FOREIGN_KEY_CHECKS=1;

-- ===== VERIFICATION =====
SELECT COUNT(*) as total_products FROM products;
SELECT COUNT(*) as jbox_fg FROM products WHERE sku REGEXP '^[0-9]' AND product_type_id = 19;
SELECT COUNT(*) as jbox_rm FROM products WHERE sku REGEXP '^[0-9]' AND product_type_id IN (17,18);
SELECT COUNT(*) as linked_headers FROM bom_headers WHERE product_id IS NOT NULL AND source = 'JBOX';
SELECT COUNT(*) as linked_details FROM bom_details WHERE raw_material_id > 0;
